import numpy as np
import pytest
from sklearn.metrics import cohen_kappa_score, matthews_corrcoef as sklearn_mcc

from agreement import cohen_kappa, matthews_corrcoef

TOL = 1e-12


def _random_problems():
    for seed in range(15):
        rng = np.random.RandomState(seed)
        y_true = rng.randint(0, 5, size=300)
        # Mix of correlated and near-random predictions across seeds.
        if seed % 3 == 0:
            y_pred = y_true.copy()
        elif seed % 3 == 1:
            noise = rng.rand(300) < 0.3
            y_pred = np.where(noise, rng.randint(0, 5, size=300), y_true)
        else:
            y_pred = rng.randint(0, 5, size=300)
        yield seed, y_true, y_pred


@pytest.mark.parametrize("weights", [None, "linear", "quadratic"])
@pytest.mark.parametrize("seed,y_true,y_pred", list(_random_problems()), ids=str)
def test_kappa_matches_sklearn(weights, seed, y_true, y_pred):
    expected = cohen_kappa_score(y_true, y_pred, weights=weights)
    assert cohen_kappa(y_true, y_pred, weights=weights) == pytest.approx(expected, abs=TOL)


@pytest.mark.parametrize("seed,y_true,y_pred", list(_random_problems()), ids=str)
def test_mcc_matches_sklearn(seed, y_true, y_pred):
    expected = sklearn_mcc(y_true, y_pred)
    assert matthews_corrcoef(y_true, y_pred) == pytest.approx(expected, abs=TOL)


@pytest.mark.parametrize("weights", [None, "linear", "quadratic"])
def test_kappa_identical_is_one(weights):
    rng = np.random.RandomState(42)
    y = rng.randint(0, 5, size=100)
    assert cohen_kappa(y, y) == 1.0


@pytest.mark.parametrize("weights", [None, "linear", "quadratic"])
def test_mcc_identical_is_one(weights):
    rng = np.random.RandomState(42)
    y = rng.randint(0, 5, size=100)
    assert matthews_corrcoef(y, y) == pytest.approx(1.0, abs=TOL)


def test_kappa_constant_prediction_not_positive():
    # Truth varied, prediction constant with below-chance accuracy -> kappa <= 0.
    y_true = np.concatenate([np.ones(250, dtype=int), np.zeros(50, dtype=int)])
    y_pred = np.ones(300, dtype=int)
    assert cohen_kappa(y_true, y_pred) <= 0.0


def test_mcc_fully_wrong_binary_is_minus_one():
    y_true = np.array([0] * 150 + [1] * 150)
    y_pred = 1 - y_true
    assert matthews_corrcoef(y_true, y_pred) == -1.0


def test_zero_denominator_returns_zero():
    # MCC degenerate: constant truth and constant identical prediction.
    y = np.zeros(10, dtype=int)
    assert matthews_corrcoef(y, y) == 0.0
    # MCC degenerate: constant prediction vs varied truth (zero column covariance).
    y_true = np.arange(10) % 3
    y_pred = np.full(10, 2)
    assert matthews_corrcoef(y_true, y_pred) == 0.0
    assert matthews_corrcoef(y_true, y_pred) == sklearn_mcc(y_true, y_pred)
    # Kappa degenerate: single class everywhere -> pe == po handled without crash.
    assert cohen_kappa(y, y) == 1.0


def test_non_contiguous_labels():
    rng = np.random.RandomState(7)
    y_true = rng.choice([2, 17, 100], size=200)
    flip = rng.rand(200) < 0.25
    y_pred = np.where(flip, rng.choice([2, 17, 100], size=200), y_true)
    for w in (None, "linear", "quadratic"):
        assert cohen_kappa(y_true, y_pred, weights=w) == pytest.approx(
            cohen_kappa_score(y_true, y_pred, weights=w), abs=TOL
        )
    assert matthews_corrcoef(y_true, y_pred) == pytest.approx(
        sklearn_mcc(y_true, y_pred), abs=TOL
    )


